{"source":"export default function draw(ctx, t) {
  const { width: w, height: h } = ctx.canvas;
  const s = Math.sin(t * 0.00015);
  const g = ctx.createLinearGradient(0, h * (0.3 + s * 0.2), w, h);
  g.addColorStop(0, '#030b1c');
  g.addColorStop(0.5, `hsl(${218 + s * 8}, 65%, 14%)`);
  g.addColorStop(1, '#08152e');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}","note":"A deep navy gradient shifts gently over time, with t in milliseconds."}
